w('        LocalDateTime startTime = LocalDateTime.parse(timeText, formatter);')
w("        Long bookingId = bookingService.createBooking(currentUser.getUserId(), slotId, startTime);")
w('        JOptionPane.showMessageDialog(this, "Booking confirmed! Booking ID: " + bookingId, ...);')
w("        loadBookingHistory();  // refresh the history tab")
