w("")
w("Step 3 - BookingService.createBooking() validates 5 rules in sequence:")
w("")
w("    // service/BookingService.java - lines 36-91")
w("    // Rule 1: start time must be in the future")
w("    if (startTime.isBefore(LocalDateTime.now()))")
w('        throw new ValidationException("Booking time must be in the future.");')
w("")
w("    // Rule 2: start minute, second, nano must all be 0 (hour-aligned booking)")
w("    if (startTime.getMinute() != 0 || startTime.getSecond() != 0 || startTime.getNano() != 0)")
w('        throw new ValidationException("Bookings must start on an exact hour (e.g., 10:00, 11:00).");')
w("")
w("    // Rule 3: slot must exist in DB and have status = ACTIVE")
w("    Optional<ChargingSlot> slotOpt = slotDAO.findById(slotId);")
w("    if (slotOpt.isEmpty()) throw new ValidationException(...);" )
w("    if (slot.getStatus() != SlotStatus.ACTIVE) throw new ValidationException(...);")
w("")
w("    // Rule 4: parent station must exist, be ACTIVE, and booking must be within operating hours")
w("    Optional<EVStation> stationOpt = stationDAO.findById(slot.getStationId());")
w("    // checks station.status == ACTIVE")
w("    // checks bookingStartLocalTime >= station.openingTime")
w("    // checks bookingEndLocalTime <= station.closingTime")
w("")
w("    // Rule 5: all checks passed - delegate to the transactional DAO")
w("    return bookingDAO.bookSlotTransactional(userId, slotId, startTime);")
w("")
w("Step 4 - BookingDAO.bookSlotTransactional() runs 4 SQL statements inside one JDBC transaction:")
w("")
w("    // dao/BookingDAO.java - lines 12-101")
w("    public synchronized Long bookSlotTransactional(...) throws SQLException {")
w("        LocalDateTime endTime = startTime.plusHours(1);")
w("")
w("        // SQL 1: Lock the slot row exclusively")
w('        "SELECT cs.slot_id, cs.status AS slot_status, cs.hourly_rate, es.status AS station_status"')
w('        "FROM charging_slots cs JOIN ev_stations es ON es.station_id = cs.station_id"')
w('        "WHERE cs.slot_id = ? FOR UPDATE"')
w("")
w("        // SQL 2: Check for time overlap with existing CONFIRMED bookings")
w('        "SELECT booking_id FROM bookings WHERE slot_id = ? AND status = \'CONFIRMED\'"')
w('        "AND start_time < ? AND end_time > ? FOR UPDATE"')
w("        // If this returns any row -> throw SQLException with 'Booking conflict' message")
w("")
w("        // SQL 3: Insert the booking")
w('        "INSERT INTO bookings (user_id, slot_id, start_time, end_time, rate_per_hour, status)"')
w('        "VALUES (?, ?, ?, ?, ?, \'CONFIRMED\')"')
w("")
w("        // SQL 4: Insert a mock payment")
w('        "INSERT INTO payments (booking_id, amount, method, status, transaction_reference)"')
w('        "VALUES (?, ?, \'MOCK\', \'PAID\', ?)"')
w("        // transaction_reference = \"TXN_MOCK_\" + UUID.randomUUID().toString().substring(0, 8).toUpperCase()")
w("")
w("        conn.setAutoCommit(false);")
w("        // ... run SQL 1, 2, 3, 4 ...")
w("        conn.commit();")
w("        return bookingId;")
w("        // on any failure: conn.rollback()")
w("    }")
w("")
w("What comes back to the screen:")
w("  Success: JOptionPane popup with the new booking_id, history tab reloads.")
w("  Conflict: overlap SQL returns a row -> SQLException('Booking conflict') thrown from DAO")
w("            -> BookingService catches it and re-throws as BookingConflictException")
w("            -> UI catches BookingConflictException and shows error popup.")
w("")
w("---")
w("")
w("## Flow C: Customer Cancels a Booking")
w("")
w("    // ui/CustomerDashboardFrame.java - lines 234-261")
w("    private void handleCancelBooking() {")
w("        Long bookingId   = (Long)   historyTableModel.getValueAt(selectedRow, 0);")
w("        String curStatus = (String) historyTableModel.getValueAt(selectedRow, 6);")
w("")
w('        if (!"CONFIRMED".equalsIgnoreCase(curStatus)) {')
w('            JOptionPane.showMessageDialog(this, "Only CONFIRMED bookings can be cancelled.", ...);')
w("            return;")
w("        }")
w("")
w('        int confirm = JOptionPane.showConfirmDialog(this, "Are you sure?", ...);')
w("        if (confirm == JOptionPane.YES_OPTION) {")
w("            try (Connection conn = DBConnection.getConnection();")
w('                 PreparedStatement stmt = conn.prepareStatement(')
w('                     "UPDATE bookings SET status = \'CANCELLED\' WHERE booking_id = ?")) {')
w("                stmt.setLong(1, bookingId);")
w("                stmt.executeUpdate();")
w("                // DB trigger fires automatically")
w("            }")
w("        }")
w("    }")
w("")
w("What happens in MySQL after that one UPDATE bookings statement:")
w("")
w("    -- dbcode.txt - lines 206-219")
w("    CREATE TRIGGER trg_booking_cancel_payment")
w("    AFTER UPDATE ON bookings")
w("    FOR EACH ROW")
w("    BEGIN")
w("        IF NEW.status = 'CANCELLED' AND OLD.status = 'CONFIRMED' THEN")
w("            UPDATE payments")
w("            SET status = 'REFUNDED', updated_at = CURRENT_TIMESTAMP")
w("            WHERE booking_id = NEW.booking_id AND status = 'PAID';")
w("        END IF;")
w("    END;")
w("")
w("Java sends only one UPDATE bookings statement.")
w("The MySQL trigger automatically changes payments.status from PAID to REFUNDED.")
w("Java does NOT call PaymentDAO.updateRefunded() for cancellation - the trigger handles it.")
w("")
