w("ev_stations (4 rows):")
w("  ID 1 : GreenPlug Central Station, Pune, ACTIVE, 06:00 to 23:00")
w("  ID 2 : PowerGrid Hub Wakad, Pune, ACTIVE, 00:00:01 to 23:59:59 (24-hour station)")
